class Solution:
    def handleQuery(self, queries: List[List[int]]) -> List[int]:
        return [self.solve(f, t, m) for f, t, m in queries]
    def cb(self, b, x):
        if x <= 0:
            return 0
        p = 1 << (b + 1)
        return (x + 1) // p * (p >> 1) + max(0, (x + 1) % p - (p >> 1))
    def F(self, x):
        return sum(self.cb(b, x) for b in range(51))
    def G(self, x):
        return sum(b * self.cb(b, x) for b in range(51))
    def bits(self, x):
        return [b for b in range(51) if (x >> b) & 1]
    def solve(self, frm, to, mod):
        def find(v):
            lo, hi = 1, to + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if self.F(mid) > v:
                    hi = mid
                else:
                    lo = mid + 1
            return lo
        x0, x1 = find(frm), find(to)
        b0, b1 = self.bits(x0), self.bits(x1)
        s0 = frm - self.F(x0 - 1)
        if x1 == x0:
            exp = sum(b0[s0:s0 + (to - frm + 1)])
        else:
            t1 = to - self.F(x1 - 1) + 1
            exp = sum(b0[s0:]) + sum(b1[:t1])
            if x1 > x0 + 1:
                exp += self.G(x1 - 1) - self.G(x0)
        return pow(2, exp, mod)

