class Solution {
public:
    vector<int> handleQuery(vector<vector<int>>& queries) {
        vector<int> out;
        for (auto& q : queries) out.push_back(solve(q[0], q[1], q[2]));
        return out;
    }
    long long cb(int b, long long x) {
        if (x <= 0) return 0;
        long long p = 1LL << (b + 1);
        return (x + 1) / p * (p / 2) + max(0LL, (x + 1) % p - p / 2);
    }
    long long F(long long x) { long long s = 0; for (int b = 0; b < 51; b++) s += cb(b, x); return s; }
    long long G(long long x) { long long s = 0; for (int b = 0; b < 51; b++) s += (long long)b * cb(b, x); return s; }
    vector<int> bits(long long x) { vector<int> r; for (int b = 0; b < 51; b++) if (x >> b & 1) r.push_back(b); return r; }
    long long findBoundary(long long v, long long hi) {
        long long lo = 1;
        while (lo < hi) { long long mid = (lo + hi) / 2; if (F(mid) > v) hi = mid; else lo = mid + 1; }
        return lo;
    }
    int solve(long long frm, long long to, int mod) {
        long long x0 = findBoundary(frm, to + 1), x1 = findBoundary(to, to + 1);
        auto b0 = bits(x0), b1 = bits(x1);
        long long s0 = frm - F(x0 - 1), exp = 0;
        if (x1 == x0) {
            for (long long i = s0; i < s0 + (to - frm + 1); i++) exp += b0[i];
        } else {
            long long t1 = to - F(x1 - 1) + 1;
            for (size_t i = s0; i < b0.size(); i++) exp += b0[i];
            for (int i = 0; i < t1; i++) exp += b1[i];
            if (x1 > x0 + 1) exp += G(x1 - 1) - G(x0);
        }
        long long r = 1 % mod, base = 2 % mod;
        while (exp) { if (exp & 1) r = r * base % mod; base = base * base % mod; exp >>= 1; }
        return r;
    }
};

