class Solution {
    public int[] handleQuery(int[][] queries) {
        int[] out = new int[queries.length];
        for (int i = 0; i < queries.length; i++)
            out[i] = solve(queries[i][0], queries[i][1], queries[i][2]);
        return out;
    }
    private long cb(int b, long x) {
        if (x <= 0) return 0;
        long p = 1L << (b + 1);
        return (x + 1) / p * (p / 2) + Math.max(0, (x + 1) % p - p / 2);
    }
    private long F(long x) { long s = 0; for (int b = 0; b < 51; b++) s += cb(b, x); return s; }
    private long G(long x) { long s = 0; for (int b = 0; b < 51; b++) s += (long) b * cb(b, x); return s; }
    private List<Integer> bits(long x) {
        List<Integer> r = new ArrayList<>();
        for (int b = 0; b < 51; b++) if ((x >> b & 1) == 1) r.add(b);
        return r;
    }
    private long findBoundary(long v, long hi) {
        long lo = 1;
        while (lo < hi) { long mid = (lo + hi) >>> 1; if (F(mid) > v) hi = mid; else lo = mid + 1; }
        return lo;
    }
    private int solve(long frm, long to, int mod) {
        long x0 = findBoundary(frm, to + 1), x1 = findBoundary(to, to + 1);
        List<Integer> b0 = bits(x0), b1 = bits(x1);
        long s0 = frm - F(x0 - 1), exp = 0;
        if (x1 == x0) {
            for (long i = s0; i < s0 + (to - frm + 1); i++) exp += b0.get((int) i);
        } else {
            long t1 = to - F(x1 - 1) + 1;
            for (int i = (int) s0; i < b0.size(); i++) exp += b0.get(i);
            for (int i = 0; i < t1; i++) exp += b1.get(i);
            if (x1 > x0 + 1) exp += G(x1 - 1) - G(x0);
        }
        long r = 1 % mod, base = 2 % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) r = r * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return (int) r;
    }
}

