var handleQuery = function(queries) {
    const cb = (b, x) => {
        if (x <= 0) return 0;
        const p = 2 ** (b + 1);
        return Math.floor((x + 1) / p) * (p / 2) + Math.max(0, (x + 1) % p - p / 2);
    };
    const F = x => { let s = 0; for (let b = 0; b < 51; b++) s += cb(b, x); return s; };
    const G = x => { let s = 0; for (let b = 0; b < 51; b++) s += b * cb(b, x); return s; };
    const bits = x => { const r = []; for (let b = 0; b < 51; b++) if (Number(x >> BigInt(b)) & 1) r.push(b); return r; };
    const findB = (v, hi) => { let lo = 1;
        while (lo < hi) { const mid = Math.floor((lo + hi) / 2); if (F(mid) > v) hi = mid; else lo = mid + 1; } return lo; };
    const solve = (frm, to, mod) => {
        const x0 = findB(frm, to + 1), x1 = findB(to, to + 1);
        const b0 = bits(x0), b1 = bits(x1);
        const s0 = frm - F(x0 - 1);
        let exp = 0;
        if (x1 === x0) {
            for (let i = s0; i < s0 + (to - frm + 1); i++) exp += b0[i];
        } else {
            const t1 = to - F(x1 - 1) + 1;
            for (let i = s0; i < b0.length; i++) exp += b0[i];
            for (let i = 0; i < t1; i++) exp += b1[i];
            if (x1 > x0 + 1) exp += G(x1 - 1) - G(x0);
        }
        let r = 1 % mod, base = 2 % mod, e = exp;
        while (e > 0) { if (e & 1) r = r * base % mod; base = base * base % mod; e >>= 1; }
        return r;
    };
    return queries.map(q => solve(q[0], q[1], q[2]));
};
